actor Correlator {
    private var pending: [String: CheckedContinuation<Reply, Error>] = [:]

    func register(_ id: String, _ continuation: CheckedContinuation<Reply, Error>) {
        pending[id] = continuation
    }
    func resume(_ id: String, with result: Result<Reply, Error>) {
        guard let continuation = pending.removeValue(forKey: id) else { return }   // late id: drop
        continuation.resume(with: result)
    }
}

let id = UUID().uuidString
let reply: Reply = try await withCheckedThrowingContinuation { continuation in
    Task { await correlator.register(id, continuation) }   // register BEFORE send
    transport.send(Request(id: id, body: body))
}
